@push('scripts')<script>const kec=document.querySelector('#kecamatan-select'),kel=document.querySelector('#kelurahan-select');const filter=()=>{if(!kec||!kel)return;[...kel.options].forEach(o=>{if(o.value)o.hidden=kec.value!==''&&o.dataset.kecamatan!==kec.value;});};kec?.addEventListener('change',filter);filter();</script>@endpush
